"""Finite rings generated by the queue handback rule.

A consumption is carried directly by its queue/controller, or by one already
required publication returning to the producer queue. This is a bounded rule
with checked premises; no arbitrary paths, execution graphs or post-selection
progress search participate. Window membership describes parametric uses,
including outer reentry. A finite upper bound can instead give one ID per use.
"""

from dataclasses import dataclass

from ..scalar import expression, literal, substitute
from .event_contracts import CROSS_BACKLOG, LOCAL_CAPACITY, CaseLease, StructuredEventLease
from .guard_cover import opposite, prove_guard_cover
from .structured_protocols import NotificationKind
from .structured_schedule import ActionGuard, Comparison


@dataclass(frozen=True, slots=True)
class Handback:
    consume: object
    next_set: object
    # None is direct queue/controller consumption. A relay is always an
    # actual, already-required notification, never a generated barrier.
    relay: object | None
    publication: object | None
    acquisition: object | None
    condition: ActionGuard


@dataclass(frozen=True, slots=True)
class Reuse:
    loop: object | None
    delta: int
    upper_uses: int | None
    condition: ActionGuard
    handbacks: tuple[Handback, ...] = ()


class HandbackRule:
    def __init__(self, domains):
        self.domains = domains
        self.peers = tuple(
            n for n in domains.notifications if n.mechanism is not NotificationKind.PIPE_FENCE
        )
        self.at_native = {}
        self.boundary_cases = {}
        for peer in self.peers:
            for source in peer.sources:
                self.at_native.setdefault((source.operation, source.actor), []).append(
                    (peer, source)
                )

    def _eligible(self, old_channel, old, target_channel, target, peer):
        return (
            any(old.actor is p.actor for p in peer.sources)
            and (
                self.domains._gate(old_channel)
                or old_channel.destination_engine is peer.source_engine
            )
            and any(target.actor is p.actor for p in peer.consumers)
            and (
                self.domains._gate(peer) or peer.destination_engine is target_channel.source_engine
            )
        )

    def _cases(self, peer):
        cases = self.domains.cases[peer]
        if self.domains.clocks[peer] and not any(c.windows for c in cases):
            if peer not in self.boundary_cases:
                from .event_families import build_event_family

                # Cell credits need no dense ordinal. A streaming caller can
                # additionally require exact invocation boundary membership.
                # Universal pairing survives this domain specialization.
                self.boundary_cases[peer] = build_event_family(self.domains, peer)
            return self.boundary_cases[peer]
        return cases

    def _step(self, bound, loop):
        d = self.domains
        task = d.dispatch.tasks[bound.operation, bound.actor]
        scope, stage = task.scope, task.stage
        while scope.operation is not loop and scope.parent is not None:
            stage, scope = scope.parent_stage, scope.parent
        if scope.operation is not loop:
            return None
        coordinate = dict(bound.coordinates).get(loop)
        if coordinate is None:
            return None
        return d.arithmetic.normalize(
            expression(
                "sub", expression("add", coordinate, literal(stage)), d.control.loops[loop].ordinal
            )
        ).constant

    def candidates(self, peers, loop, delta, *, reentry, old, target):
        d = self.domains
        if loop is None:
            for peer in peers:
                for case in self._cases(peer):
                    if not case.empty:
                        for sources, consumers in d._instances(peer, case, None, 0):
                            yield peer, sources, consumers
            return
        begin, end = self._step(old, loop), self._step(target, loop)
        for peer in peers:
            starts = [self._step(p, loop) for p in peer.sources]
            stops = [self._step(p, loop) for p in peer.consumers]
            repeated = loop in d.clocks[peer]
            if repeated and any(s is None for s in starts + stops):
                continue
            if repeated and begin is not None and end is not None:
                offsets = range(begin - max(starts), end - min(stops) + 1)
            elif repeated:
                # Non-unit selected/reentry coordinates cannot supply a
                # constant finite handback horizon under this rule.
                continue
            else:
                offsets = (0,)
            for case in self._cases(peer):
                if case.empty:
                    continue
                for offset in offsets:
                    yield from (
                        (peer, sources, consumers)
                        for sources, consumers in d._instances(peer, case, loop, offset)
                    )

    def establish(self, channel, old, target_channel, target, assumptions, *, loop, delta, reentry):
        d = self.domains
        conditions, handbacks = [], []

        def add(guard, relay=None, source=None, wait=None):
            remaining = []
            for test in guard.comparisons:
                premises = assumptions + tuple(remaining)
                if d.arithmetic.prove(test, premises):
                    continue
                if d.arithmetic.prove(opposite(test), premises):
                    return
                remaining.append(test)
            guard = ActionGuard(tuple(dict.fromkeys(remaining)))
            if guard in conditions:
                return
            conditions.append(guard)
            handbacks.append(Handback(old, target, relay, source, wait, guard))

        def covered():
            return prove_guard_cover(d.arithmetic, assumptions, tuple(conditions)) is not None

        for condition in d._following_conditions(channel, old, target_channel, target):
            add(condition)
        if covered():
            return tuple(handbacks)
        peers = tuple(
            p
            for p in self.peers
            if p is not channel and self._eligible(channel, old, target_channel, target, p)
        )
        for peer, sources, consumers in self.candidates(
            peers, loop, delta, reentry=reentry, old=old, target=target
        ):
            d.work.handback_candidates += 1
            active = tuple(
                dict.fromkeys(t for p in sources + consumers for t in p.guard.comparisons)
            )
            for source in sources:
                first = d._following_conditions(channel, old, peer, source)
                if not first:
                    continue
                for wait in consumers:
                    last = d._following_conditions(peer, wait, target_channel, target)
                    for a in first:
                        for b in last:
                            guard = ActionGuard(
                                tuple(dict.fromkeys(active + a.comparisons + b.comparisons))
                            )
                            add(guard, peer, source, wait)
            if covered():
                return tuple(handbacks)
        # Compose two required handoffs at one *actual native occurrence*.
        # This is the MTE2 -> Vector -> MTE3 rule (and the same general
        # native-boundary rule on Cube), not arbitrary interface path search.
        first_peers = tuple(
            p
            for p in self.peers
            if p is not channel
            and any(old.actor is s.actor for s in p.sources)
            and (d._gate(channel) or channel.destination_engine is p.source_engine)
        )
        for peer, sources, consumers in self.candidates(
            first_peers, loop, delta, reentry=reentry, old=old, target=target
        ):
            for middle in consumers:
                for second, second_source in self.at_native.get(
                    (middle.operation, middle.actor), ()
                ):
                    if (
                        second in (channel, peer)
                        or not any(target.actor is w.actor for w in second.consumers)
                        or not (
                            d._gate(second)
                            or second.destination_engine is target_channel.source_engine
                        )
                    ):
                        continue
                    actual = {d.control.loops[l].ordinal: v for l, v in middle.coordinates}
                    bindings = {
                        ordinal: substitute(second_source.expression(ordinal), actual)
                        for ordinal in actual
                    }
                    for case in d.cases[second]:
                        if case.empty:
                            continue
                        d.work.handback_compositions += 1
                        ss = d._instance(second_source, bindings, case=case)
                        match = tuple(
                            Comparison(v, "==", dict(ss.coordinates)[l])
                            for l, v in middle.coordinates
                            if l in dict(ss.coordinates)
                        )
                        active = (
                            tuple(
                                t for p in sources + consumers + (ss,) for t in p.guard.comparisons
                            )
                            + match
                        )
                        for source in sources:
                            first = d._following_conditions(channel, old, peer, source)
                            for wait in (
                                d._instance(p, bindings, case=case) for p in second.consumers
                            ):
                                last = d._following_conditions(second, wait, target_channel, target)
                                for a in first:
                                    for b in last:
                                        guard = ActionGuard(
                                            tuple(
                                                dict.fromkeys(
                                                    active
                                                    + wait.guard.comparisons
                                                    + a.comparisons
                                                    + b.comparisons
                                                )
                                            )
                                        )
                                        add(guard, (peer, second), (source, ss), (middle, wait))
                        if covered():
                            return tuple(handbacks)
        return None

    def reuse(self, channel, case, window, width, *, reentry):
        d, loop = self.domains, window.loop
        ordinal = d.control.loops[loop].ordinal
        result = []
        for phase, delta in window.reuse_phases(width):
            if reentry:
                old_sources, old_waits = list(d._instances(channel, case, loop, 0))[-1]
                next_sources, next_waits = next(d._instances(channel, case, loop, delta))
            else:
                shifted = {ordinal: expression("add", ordinal, literal(delta))}
                old_sources = tuple(d._instance(p, {}, case=case) for p in channel.sources)
                old_waits = tuple(d._instance(p, {}, case=case) for p in channel.consumers)
                next_sources = tuple(d._instance(p, shifted, case=case) for p in channel.sources)
                next_waits = tuple(d._instance(p, shifted, case=case) for p in channel.consumers)
            condition = ActionGuard(
                tuple(dict.fromkeys(case.condition.comparisons + phase.comparisons))
            )
            assumptions = tuple(
                dict.fromkeys(
                    condition.comparisons
                    + tuple(
                        t
                        for p in old_sources + old_waits + next_sources + next_waits
                        for t in p.guard.comparisons
                    )
                )
            )
            handbacks = []
            for old in old_waits:
                for target in next_sources:
                    rule = self.establish(
                        channel,
                        old,
                        channel,
                        target,
                        assumptions,
                        loop=loop,
                        delta=delta,
                        reentry=reentry,
                    )
                    if rule is None:
                        return None
                    handbacks.extend(rule)
            result.append(Reuse(loop, delta, None, condition, tuple(handbacks)))
        return tuple(result)

    def case(self, channel, case):
        d = self.domains
        d.work.ring_cases += 1
        cross = channel.mechanism is NotificationKind.CROSS_EVENT
        capacity = CROSS_BACKLOG if cross else LOCAL_CAPACITY
        width, rings, inside, reentries = 1, [], [], []
        if not case.windows:
            inside.append(Reuse(None, 0, 1, case.condition))
        for index in reversed(range(len(case.windows))):
            window = case.windows[index]
            for candidate in range(1, capacity // width + 1):
                if window.upper is not None and window.upper <= candidate:
                    uses = (Reuse(window.loop, 0, window.upper, case.condition),)
                else:
                    uses = self.reuse(
                        channel, case, window, candidate, reentry=index < len(case.windows) - 1
                    )
                if uses is not None:
                    break
            else:
                d.fail(
                    channel,
                    "queue handback rule cannot establish consumption before reuse within event capacity",
                    phase="notification-generation-lifetime",
                )
            width *= candidate
            rings.insert(0, (window, candidate))
            (inside if index == len(case.windows) - 1 else reentries).extend(uses)
        ordinal = literal(0)
        for window, ring in rings:
            local = (
                literal(0)
                if window.single or ring == 1
                else expression("rem", window.rank(), literal(ring))
            )
            ordinal = expression("add", expression("mul", ordinal, literal(ring)), local)
        return CaseLease(
            case,
            1 if cross else width,
            ordinal,
            tuple(rings),
            tuple(inside),
            tuple(reentries),
            width if cross else None,
        )

    def leases(self):
        return tuple(self.lease(n) for n in self.peers)

    def lease(self, notification):
        cases = tuple(
            self.case(notification, c)
            for c in self.domains.cases[notification]
            if self.domains.active[notification, c]
        )
        return StructuredEventLease(notification, max((c.width for c in cases), default=0), cases)
